       ClockExpiry::Mulligan => {
           if self.mulligan_open && self.mulligan_expired && self.mulligan.timer.is_none() {
               self.mulligan_expired = false;
               self.mulligan.deadline = Some(now_ms() + ms);
               self.open_mulligan();
